import net from "node:net";

export interface RelayEndpoint {
  host: string;
  port: number;
}

export interface ProbeResult {
  endpoint: RelayEndpoint;
  healthy: boolean;
  rttMs?: number;
  error?: string;
}

const PING = Buffer.from("PING\n");
const PONG = "PONG";

export function probeRelay(endpoint: RelayEndpoint, timeoutMs: number): Promise<ProbeResult> {
  return new Promise((resolve) => {
    const started = Date.now();
    const socket = net.createConnection({ host: endpoint.host, port: endpoint.port });
    let received = "";
    let settled = false;

    const finish = (result: Omit<ProbeResult, "endpoint">) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      socket.removeAllListeners("data");
      socket.destroy();
      resolve({ endpoint, ...result });
    };

    const timer = setTimeout(() => {
      finish({ healthy: false, error: `timeout after ${timeoutMs}ms` });
    }, timeoutMs);

    socket.setNoDelay(true);
    socket.once("connect", () => {
      socket.write(PING);
    });
    socket.on("data", (chunk: Buffer) => {
      received += chunk.toString("utf8");
      if (received.length > 64) {
        finish({ healthy: false, error: "unexpected response" });
        return;
      }
      if (received.includes("\n")) {
        const line = received.trim();
        if (line === PONG) {
          finish({ healthy: true, rttMs: Date.now() - started });
        } else {
          finish({ healthy: false, error: `unexpected response: ${line}` });
        }
      }
    });
    socket.on("error", (err) => {
      finish({ healthy: false, error: err.message });
    });
    socket.on("close", () => {
      finish({ healthy: false, error: "closed before reply" });
    });
  });
}

import { probeRelay, ProbeResult, RelayEndpoint } from "./relayProbe";

export interface RelayRegistry {
  list(): RelayEndpoint[];
  markHealth(endpoint: RelayEndpoint, healthy: boolean, rttMs?: number): void;
}

export interface MonitorOptions {
  intervalMs: number;
  probeTimeoutMs: number;
  maxConcurrentProbes: number;
}

export class RelayHealthMonitor {
  private timer?: NodeJS.Timeout;
  private sweeping = false;

  constructor(private readonly registry: RelayRegistry, private readonly opts: MonitorOptions) {}

  start(): void {
    if (this.timer) return;
    this.timer = setInterval(() => void this.sweep(), this.opts.intervalMs);
  }

  stop(): void {
    if (this.timer) clearInterval(this.timer);
    this.timer = undefined;
  }

  async sweep(): Promise<ProbeResult[]> {
    if (this.sweeping) return [];
    this.sweeping = true;
    try {
      const endpoints = this.registry.list();
      const results: ProbeResult[] = [];
      let next = 0;
      const worker = async () => {
        while (next < endpoints.length) {
          const ep = endpoints[next++];
          const r = await probeRelay(ep, this.opts.probeTimeoutMs);
          this.registry.markHealth(r.endpoint, r.healthy, r.rttMs);
          results.push(r);
        }
      };
      const n = Math.min(this.opts.maxConcurrentProbes, endpoints.length);
      await Promise.all(Array.from({ length: n }, worker));
      return results;
    } finally {
      this.sweeping = false;
    }
  }
}
